import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.BKVF-9lJ.js";const u=JSON.parse('{"title":"mfe-forge build","description":"","frontmatter":{},"headers":[],"relativePath":"cli/build.md","filePath":"cli/build.md","lastUpdated":1791840224000}'),s={name:"cli/build.md"};function i(r,e,c,l,n,p){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="mfe-forge-build" tabindex="-1"><code>mfe-forge build</code> <a class="header-anchor" href="#mfe-forge-build" aria-label="Permalink to &quot;`mfe-forge build`&quot;">​</a></h1><p>Build discovered applications for production by running each one&#39;s <code>build</code> script.</p><h2 id="synopsis" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mfe-forge build [app] [options]</span></span></code></pre></div><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>build</code> resolves its targets, then runs <code>&lt;pm&gt; run build</code> in each app directory (<code>apps/&lt;scope&gt;/&lt;name&gt;</code>) <strong>sequentially</strong>, with output captured. By default every target is attempted, failures are collected, and a summary is printed at the end.</p><p>Targets are apps discovered under <code>apps/&lt;scope&gt;/&lt;name&gt;/</code> with a <code>vite.config.ts</code>, hosts included. <code>packages/*</code> libraries and design systems are not built by this command; build them with their own scripts.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>app</code></td><td>No</td><td>One app, as <code>scope/name</code> or a bare name that is unique across scopes.</td></tr></tbody></table><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-s</code>, <code>--scope &lt;scope&gt;</code></td><td>string</td><td></td><td>Build every app in the scope (ignored when <code>app</code> is given).</td></tr><tr><td><code>--bail</code></td><td>boolean</td><td><code>false</code></td><td>Stop after the first failed build. Remaining targets are reported as skipped.</td></tr><tr><td><code>--parallel</code></td><td>boolean</td><td><code>false</code></td><td>Accepted for compatibility. Builds still run sequentially.</td></tr><tr><td><code>--analyze</code></td><td>boolean</td><td><code>false</code></td><td>Accepted but <strong>not implemented</strong>; no bundle analysis is produced.</td></tr><tr><td><code>-h</code>, <code>--help</code></td><td>boolean</td><td></td><td>Show help.</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # all apps</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop/cart</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # resolves admin/users if unique</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scope</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bail</span></span></code></pre></div><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>For each target, a spinner reports <code>Built &lt;app&gt;</code> or <code>Failed to build &lt;app&gt;</code>, followed by the captured stderr (or the error message). The run ends with a summary:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✔ built 2, ✖ failed 1, ○ skipped 0</span></span></code></pre></div><p><code>○ skipped</code> appears only when <code>--bail</code> stopped the run early.</p><h2 id="failure-modes" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td><code>app</code> does not resolve (unknown or ambiguous)</td><td><code>App &quot;&lt;app&gt;&quot; not found</code>, exit <code>1</code>. No build runs.</td></tr><tr><td><code>--scope</code> matches no apps</td><td><code>No apps found in scope &quot;&lt;scope&gt;&quot;</code>, exit <code>1</code>.</td></tr><tr><td>One or more builds fail</td><td><code>Build failed for: &lt;a&gt;, &lt;b&gt;</code>, exit <code>2</code>.</td></tr><tr><td>Configuration invalid</td><td>Exit <code>3</code>.</td></tr></tbody></table><p>An empty project (no apps, no filter) prints <code>Building 0 application(s)</code> and exits <code>0</code>.</p><hr><h2 id="mfe-forge-test" tabindex="-1"><code>mfe-forge test</code> <a class="header-anchor" href="#mfe-forge-test" aria-label="Permalink to &quot;`mfe-forge test`&quot;">​</a></h2><p>Run a test script for the workspace or for a single app.</p><h3 id="synopsis-1" tabindex="-1">Synopsis <a class="header-anchor" href="#synopsis-1" aria-label="Permalink to &quot;Synopsis&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mfe-forge test [app] [options]</span></span></code></pre></div><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-u</code>, <code>--unit</code></td><td>boolean</td><td><code>false</code></td><td>Run the <code>test:unit</code> script instead of <code>test</code>.</td></tr><tr><td><code>-e</code>, <code>--e2e</code></td><td>boolean</td><td><code>false</code></td><td>Run the <code>test:e2e</code> script instead of <code>test</code>.</td></tr><tr><td><code>-c</code>, <code>--coverage</code></td><td>boolean</td><td><code>false</code></td><td>Forward <code>--coverage</code> to the script.</td></tr><tr><td><code>-w</code>, <code>--watch</code></td><td>boolean</td><td><code>false</code></td><td>Forward <code>--watch</code> to the script.</td></tr></tbody></table><h3 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h3><ul><li>Without <code>app</code>, the command runs <code>&lt;pm&gt; run &lt;script&gt;</code> in the workspace root. With <code>app</code>, it runs in <code>apps/&lt;scope&gt;/&lt;name&gt;</code>.</li><li>Forwarded flags are appended after <code>--</code>, for example <code>bun run test -- --coverage</code>.</li><li>Output is streamed (<code>stdio: inherit</code>).</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Generated apps define <code>test</code> and <code>test:e2e</code> but no <code>test:unit</code>, so <code>--unit</code> fails unless you add that script. The <code>init</code> template&#39;s root <code>test</code> script is <code>mfe-forge test</code>; running <code>mfe-forge test</code> from the root without your own root test script therefore calls itself recursively. Replace the root <code>test</code> script with your actual runner.</p></div><h3 id="failure-modes-1" tabindex="-1">Failure modes <a class="header-anchor" href="#failure-modes-1" aria-label="Permalink to &quot;Failure modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td><code>--unit</code> and <code>--e2e</code> together</td><td><code>Use either --unit or --e2e, not both</code>, exit <code>1</code>.</td></tr><tr><td><code>app</code> not found</td><td>exit <code>1</code>.</td></tr><tr><td>Script fails or is missing</td><td><code>Tests failed</code>, exit <code>2</code>.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./dev"><code>dev</code></a></li><li><a href="./doctor"><code>doctor</code></a></li><li><a href="./../packages/testing">Testing package</a></li></ul>',34)])])}const b=t(s,[["render",i]]);export{u as __pageData,b as default};
